'use strict';
const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{execFileSync}=require('node:child_process'),{chromium}=require('playwright'),{parse}=require('../audits/audit-i18n-global.cjs');
const repo=path.resolve(__dirname,'../..'),root=process.env.TABLEAU_ORGANISATIONS_ASSET_DIR||repo,read=f=>fs.readFileSync(path.join(root,f),'utf8'),base='a7ce1e08d59317bbd7aa02c1fbdfbf4f95cc1afe',old=execFileSync('git',['show',base+':plateau-organisations-quetes.js'],{cwd:repo,encoding:'utf8',maxBuffer:4e6}),rows=JSON.parse(fs.readFileSync(path.join(repo,'outils/audits/I18N-TABLEAU-ORGANISATIONS-871-sources.json'))).rows,types=Object.fromEntries(rows.filter(r=>r[0].startsWith('type_')).map(([k,label])=>[k.slice(5),{label}])),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'];
const selected=s=>{const n=parse(s).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='ouvrirTableauOrganisations');assert.ok(n);return s.slice(n.start,n.end);};
const org=(type,more={})=>({id:'fixture',type,nom:'Tableau des organisations',visible:true,chef:'Chef Fixture',fondateur:'Fondateur Fixture',country:'republic',city:'ville_a',localId:'hotel:salon',membres:[],...more});
const cases=[];for(const type of Object.keys(types)){cases.push({id:type+' public',orgs:[org(type)]});cases.push({id:type+' secret visiteur',hidden:true,orgs:[org(type,{visible:false,chef:'CHEF_MASQUE',localId:'secret:cache',membres:[{nom:'Autre Joueur'}]})]});cases.push({id:type+' secret membre ordinaire',orgs:[org(type,{visible:false,membres:[{nom:'PJ Fixture',grade:'Membre'}]})]});}
cases.push({id:'lieu canonique avec entité HTML',orgs:[org('politique',{localId:'chasse-peche-psm:rayon'})]},{id:'vide',orgs:[]},{id:'type inconnu',orgs:[org('type_libre')]},{id:'siège inconnu',orgs:[org('politique',{localId:''})]},{id:'fondateur',orgs:[org('politique',{chef:''})]},{id:'supporters sans surcharge',orgs:[org('supporters',{country:'orphan'})]},{id:'personnage absent',hidden:true,char:null,orgs:[org('politique',{visible:false,chef:'CHEF_MASQUE',localId:'secret:cache'})]},{id:'empire inconnu',orgs:[org('politique',{country:'unlisted_country'})]},{id:'champs manquants',orgs:[{id:'vide',type:'',nom:null,visible:true}]},{id:'pays origine prioritaire et plusieurs groupes',orgs:[org('politique',{country:'republic',country_origine:'soviet'}),org('religieuse',{id:'autre',country:undefined})]});
async function setup(page,before){await page.route('**/*',r=>r.abort());await page.setContent('<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body class="plateau-body"><input id="draft" value="Brouillon conservé"><div id="modal-postes" class="modal-overlay"><div class="modal-box"><div class="modal-header"><div id="postes-modal-title" class="modal-title"></div><button class="modal-close" aria-label="Fermer">×</button></div><div id="postes-body" class="modal-body"></div></div></div></body></html>');await page.addStyleTag({content:read('style.css')});await page.addScriptTag({content:read('i18n/i18next.min.js')});await page.evaluate(types=>{window.RP_I18N_GAME_ENABLED=true;window.RPPlateauI18n={language:()=>i18next.language||'fr'};window.TYPES_ORGANISATIONS=types;window.COUNTRIES={republic:{n:'Republia'},soviet:{n:'Sovarka'}};window.BUILDINGS={'chasse-peche-psm':{shortName:'Chasse &amp; Pêche',rooms:{rayon:{name:'Atelier &amp; Réserve'}}},hotel:{name:'Hôtel de Ville',rooms:{salon:{name:'Salle du Conseil'}}},secret:{name:'ADRESSE_MASQUEE',rooms:{cache:{name:'SALLE_MASQUEE'}}},stade:{name:'Stade',rooms:{siege_supporters:{name:'Siège des Supporters'}}}};window.WORLD={republic:{ville_a:{buildingContext:{stade:{roomOverrides:{siege_supporters:{name:'Local des Tribunes'}}}}}},soviet:{ville_a:{buildingContext:{}}}};window.calls=[];window.renderCount=0;window.state={char:{name:'PJ Fixture'},pa:13,arg:4000,inventory:[{id:'intact'}],progression:{stage:3},country:'republic',organisations:[]};for(const f of ['fetch','sbRpc','saveState','doOrder','deduireCoutOrdre'])window[f]=(...a)=>{calls.push([f,...a]);throw Error('Appel métier interdit');};window.snapshot=()=>JSON.stringify({state,calls,renderCount});window.ui=()=>JSON.stringify({draft:document.getElementById('draft').value,focus:document.activeElement.id,start:document.getElementById('draft').selectionStart,end:document.getElementById('draft').selectionEnd,scroll:[scrollX,scrollY,document.querySelector('.modal-box').scrollTop,document.getElementById('postes-body').scrollTop]});document.querySelector('.modal-close').onclick=()=>document.getElementById('modal-postes').classList.remove('open');},types);for(const f of ['i18n/resources.js','i18n/plateau-resources.js','i18n/organization-directory-resources.js','i18n/plateau-init.js'])await page.addScriptTag({content:read(f)});await page.evaluate(async()=>{await i18next.changeLanguage('fr');document.getElementById('draft').focus();document.getElementById('draft').setSelectionRange(2,6);});await page.addScriptTag({content:selected(before?old:read('plateau-organisations-quetes.js'))+'\nconst nativeTableau=ouvrirTableauOrganisations;window.ouvrirTableauOrganisations=()=>{renderCount++;return nativeTableau();};'});}
async function open(page,c){return page.evaluate(c=>{state.organisations=c.orgs;state.char=Object.hasOwn(c,'char')?c.char:{name:'PJ Fixture'};ouvrirTableauOrganisations();return {text:document.getElementById('postes-body').textContent,title:document.getElementById('postes-modal-title').textContent,state:JSON.stringify(state)};},c);}
test('organisations : 999 bascules, 37 états, français/confidentialité identiques à main, neuf langues et 320/390/1280 sans appel ni dépense',async()=>{
 const browser=await chromium.launch({headless:true,executablePath:process.env.CHROMIUM_PATH||'/usr/bin/chromium',args:['--no-sandbox']});let switches=0;assert.equal(cases.length,37);
 try{for(const width of [320,390,1280]){const page=await browser.newPage({viewport:{width,height:900}}),before=await browser.newPage({viewport:{width,height:900}}),errors=[],requests=[];page.on('pageerror',e=>errors.push(String(e)));page.on('request',r=>requests.push(r.url()));await setup(page,false);await setup(before,true);
 for(const example of cases){for(const p of [page,before])await p.evaluate(()=>i18next.changeLanguage('fr'));assert.deepEqual(await open(page,example),await open(before,example),example.id+' : français entier et état identiques');const business=await page.evaluate(()=>snapshot()),ui=await page.evaluate(()=>ui());for(const lang of langs){await page.evaluate(lang=>i18next.changeLanguage(lang),lang);assert.equal(await page.evaluate(()=>snapshot()),business);assert.equal(await page.evaluate(()=>ui()),ui);assert.equal(await page.locator('#postes-modal-title').textContent(),await page.evaluate(()=>i18next.t('organizationDirectory.title')));for(const node of await page.locator('#modal-postes [data-i18n]').all()){const key=await node.getAttribute('data-i18n');assert.equal(await node.textContent(),await page.evaluate(key=>i18next.t(key),key));assert.equal(await node.getAttribute('dir'),lang==='ar'?'rtl':null);}if(example.hidden){const html=await page.locator('#postes-body').innerHTML();for(const secret of ['CHEF_MASQUE','ADRESSE_MASQUEE','SALLE_MASQUEE'])assert.ok(!html.includes(secret));}if(example.orgs.length)for(const o of example.orgs)assert.ok((await page.locator('#postes-body').textContent()).includes(String(o.nom)));assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth>innerWidth),false,example.id+'/'+lang+'/'+width);assert.equal(await page.locator('.modal-box').evaluate(e=>e.scrollWidth>e.clientWidth),false,example.id+'/'+lang+'/'+width);switches++;}}
 // Le nom peut ressembler à un texte UI ou contenir des balises : aucune traduction automatique.
 const name='<span data-i18n="toastTitles.error">Nom 原 & اسم</span>',leader='Chef : non communiqué · Siège : non communiqué';await page.evaluate(()=>{BUILDINGS.hotel.name='Siège inconnu';BUILDINGS.hotel.rooms.salon.name='<b>Salle 原 & اسم</b>';});await open(page,{orgs:[org('politique',{nom:name,chef:leader})]});const opaque=await page.evaluate(()=>snapshot());for(const lang of langs){await page.evaluate(lang=>i18next.changeLanguage(lang),lang);const text=await page.locator('#postes-body').textContent();for(const value of [name,leader,'Siège inconnu','<b>Salle 原 & اسم</b>'])assert.ok(text.includes(value));assert.equal(await page.locator('#postes-body [data-i18n="toastTitles.error"],#postes-body b').count(),0);assert.equal(await page.evaluate(()=>snapshot()),opaque);assert.equal(await page.locator('.modal-box').evaluate(e=>e.scrollWidth>e.clientWidth),false);}
 // Dans une liste longue, le même élément reste visible : aucun retour au début ni reconstruction.
 await open(page,{orgs:Array.from({length:36},(_,i)=>org('politique',{id:'position_'+i,nom:'Organisation '+i}))});
 await page.locator('.hg-organisations > div').nth(17).scrollIntoViewIfNeeded();
 await page.evaluate(()=>{window.keptOrganization=document.querySelector('.hg-organisations').children[17];});
 const scrolledState=await page.evaluate(()=>snapshot());
 for(const lang of langs){await page.evaluate(lang=>i18next.changeLanguage(lang),lang);assert.equal(await page.evaluate(()=>snapshot()),scrolledState);assert.equal(await page.evaluate(()=>keptOrganization===document.querySelector('.hg-organisations').children[17]),true);assert.ok(await page.locator('.modal-box').evaluate(e=>e.scrollTop)>0);const rect=await page.evaluate(()=>{const r=keptOrganization.getBoundingClientRect();return {top:r.top,bottom:r.bottom};});assert.ok(rect.top>=0&&rect.bottom<=900);}
 await page.evaluate(()=>{TYPES_ORGANISATIONS.politique.label='Libellé nouveau du designer';});await open(page,{orgs:[org('politique')]});await page.evaluate(()=>i18next.changeLanguage('de'));assert.ok((await page.locator('#postes-body').textContent()).includes('Libellé nouveau du designer'));assert.equal(await page.locator('[data-i18n="organizationDirectory.type_politique"]').count(),0);
 await page.evaluate(()=>{TYPES_ORGANISATIONS.politique.label=RP_I18N_RESOURCES.fr.translation.organizationDirectory.type_politique;delete i18next.getResourceBundle('de','translation').organizationDirectory.type_politique;});await open(page,{orgs:[org('politique')]});assert.equal(await page.locator('[data-i18n="organizationDirectory.type_politique"]').textContent(),'Organisation Politique');
 // Le titre appartient à son span : une autre fenêtre détruit le marqueur sans être retraduite.
 await page.evaluate(()=>{document.getElementById('postes-modal-title').textContent='Fenêtre voisine';document.getElementById('postes-body').innerHTML='<p>Corps libre conservé</p>';});await page.evaluate(()=>i18next.changeLanguage('ar'));assert.equal(await page.locator('#postes-modal-title').textContent(),'Fenêtre voisine');assert.equal(await page.locator('#postes-body').textContent(),'Corps libre conservé');
 for(let n=0;n<3;n++){await open(page,{orgs:[]});const snapshot=await page.evaluate(()=>snapshot());await page.locator('.modal-close').click();await page.evaluate(()=>i18next.changeLanguage('en'));assert.equal(await page.locator('#modal-postes').evaluate(e=>e.classList.contains('open')),false);assert.equal(await page.evaluate(()=>snapshot()),snapshot);}
 await page.evaluate(()=>{window.RPI18nPlateau=undefined;});const fallback=await open(page,{orgs:[]});assert.equal(fallback.title,'Tableau des organisations');assert.equal(fallback.text,"Aucune organisation connue pour l'instant.");assert.deepEqual(errors,[]);assert.deepEqual(requests,[]);await page.close();await before.close();}
 assert.equal(switches,999);
 }finally{await browser.close();}
});
